import { InvalidValueError } from '../errors/DomainError';

/** An immutable calendar instant by which a task should be completed. */
export class DueDate {
  private constructor(private readonly value: Date) {}

  static fromString(raw: string): DueDate {
    const date = new Date(raw);
    if (raw.trim() === '' || Number.isNaN(date.getTime())) {
      throw new InvalidValueError(`Invalid due date "${raw}"`);
    }
    return new DueDate(date);
  }

  toISOString(): string {
    return this.value.toISOString();
  }
}

=====SOURCE-END=====

