import { InvalidValueError } from '../errors/DomainError';

export const TASK_STATUSES = ['todo', 'in_progress', 'done'] as const;

export type TaskStatus = (typeof TASK_STATUSES)[number];

export function parseTaskStatus(value: string): TaskStatus {
  const status = TASK_STATUSES.find((candidate) => candidate === value);
  if (status === undefined) {
    throw new InvalidValueError(`Invalid task status "${value}". Expected one of: ${TASK_STATUSES.join(', ')}`);
  }
  return status;
}

